function renderCart(){drafts?.changed();const target=$('#cart');if(!target)return;target.innerHTML=cart.map((c,i)=>`<div class="cart-item"><b>${safe(c.name)}</b><span>${clp(c.price)}</span><small>${c.options.map(o=>safe(o.name)+(o.price_delta?' (+'+clp(o.price_delta)+')':'')).join(', ')||(c.notes?'Con indicaciones para cocina':'Sin cambios · receta original')}${configuredGroups(c.product_id,groups,options).some(g=>!validateSelection(g,c.options.filter(o=>o.group_id===g.id).map(o=>o.option_id)))?'<br><b>Elige las opciones obligatorias en Editar</b>':''}${c.notes?'<br>Preparación: '+safe(c.notes):''}</small><div class="actions"><button type="button" class="quiet" data-minus="${i}" aria-label="Restar unidad">−</button><b>${c.quantity}</b><button type="button" class="quiet" data-plus="${i}" aria-label="Sumar unidad">+</button><button type="button" class="quiet" data-duplicate="${i}">Duplicar</button><button type="button" class="quiet" data-edit="${i}">Editar</button><button type="button" class="quiet" data-remove="${i}">Quitar</button></div></div>`).join('')+`<h3>Subtotal: ${clp(cartSubtotal(cart))}</h3>`;
  target.querySelectorAll('[data-minus]').forEach(b=>b.onclick=()=>{const i=+b.dataset.minus;if(cart[i].quantity>1)cart[i].quantity--;else cart.splice(i,1);renderCart()});
  target.querySelectorAll('[data-plus]').forEach(b=>b.onclick=()=>{const i=+b.dataset.plus;if(cart[i].quantity<30)cart[i].quantity++;renderCart()});
  target.querySelectorAll('[data-duplicate]').forEach(b=>b.onclick=()=>{const item=cart[+b.dataset.duplicate];cart.push({...item,quantity:1,options:item.options.map(o=>({...o}))});renderCart()});
  target.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>addProduct(cart[+b.dataset.edit].product_id,+b.dataset.edit));
  target.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{cart.splice(+b.dataset.remove,1);renderCart()});
}
async function createOrder(e){
  e.preventDefault();if(!cart.length)return alert('Agrega productos');
  const submit=e.submitter;if(submit.disabled||submittingOrder)return;submit.disabled=true;submittingOrder=true;$('#view').inert=true;const requestId=drafts.current().id;
  try{
    await loadCatalog();const revised=repriceCart(cart,products,categories,groups,options);
    if(JSON.stringify(revised)!==JSON.stringify(cart)){cart=revised;renderCart();return alert('La carta cambió. Se actualizó el precio o detalle del pedido; revísalo y vuelve a registrarlo.');}
    const f=new FormData(e.target),delivery=f.get('fulfillment')==='delivery';let quote=null;
    if(delivery){if(!String(f.get('address')).trim())return alert('Ingresa calle, número y comuna.');if(!deliveryController?.getManual())quote=deliveryController?.getQuote()||await deliveryController?.calculate();if(!quote&&!deliveryController?.getManual())throw Error('Espera a que termine el cálculo del reparto.');}
    await drafts.flush();
    const payload={name:f.get('name'),phone:f.get('phone'),fulfillment:f.get('fulfillment'),channel:f.get('channel'),whatsapp_text:f.get('whatsapp_text'),address:delivery?f.get('address'):null,quote_id:quote?.id||null,manual_delivery:delivery?deliveryController?.getManual():null,items:cart.map(c=>({product_id:c.product_id,quantity:c.quantity,options:c.options.map(o=>({group_id:o.group_id,option_id:o.option_id})),notes:c.notes||''})),...readExtras(e.target)};
    const {data,error}=await sb.rpc('staff_submit_order',{p_data:payload,p_request:requestId});if(error)throw error;
    await drafts.completed(requestId);cart=[];
    alert('Pedido registrado. Comanda enviada a la cola de impresión.');
    submittingOrder=false;$('#view').inert=false;page('Pedidos');
  }catch(error){err(error);}finally{submittingOrder=false;$('#view').inert=false;submit.disabled=false;}
}
