  const {mountDeliverySettings}=await import('./delivery-ui.js');if(activePage!=='Configuración')return;mountDeliverySettings({target:$('#deliverySettingsPanel'),settings:data,client:sb,onSaved:renderSettings});$('#openCatalog').onclick=()=>page('Carta');
