async function renderOverview(){
  if(profile.role!=='owner')return;
  const day=new Date().toLocaleDateString('en-CA',{timeZone:'America/Santiago'}),input=window.reportDay||day;
  const start=new Date(input+'T00:00:00'),end=new Date(start);end.setDate(end.getDate()+1);
  const [movementsResult,suppliersResult]=await Promise.all([
    sb.from('cash_movements').select('order_id,amount,kind,method,description,created_at,supplier_payment_id').gte('created_at',start.toISOString()).lt('created_at',end.toISOString()).limit(1000),
    sb.from('supplier_payments').select('id,supplier_name,amount,method,paid_at,status').gte('paid_at',start.toISOString()).lt('paid_at',end.toISOString()).limit(1000)]);
  const failure=[movementsResult,suppliersResult].find(r=>r.error);if(failure)return err(failure.error);
  const ids=[...new Set(movementsResult.data.filter(x=>x.order_id).map(x=>x.order_id))];
  const orderBatches=await Promise.all(Array.from({length:Math.ceil(ids.length/100)},(_,i)=>sb.from('orders').select('id,order_number,source_channel').in('id',ids.slice(i*100,(i+1)*100))));
  const orderFailure=orderBatches.find(x=>x.error);if(orderFailure)return err(orderFailure.error);
  const ordersResult={data:orderBatches.flatMap(x=>x.data||[])};
  const summary=financeSummary(ordersResult.data,movementsResult.data,suppliersResult.data);
  $('#view').innerHTML=`<h1>Resumen del negocio</h1><label>Fecha<input id="reportDate" type="date" value="${safe(input)}"></label><div class="summary-grid"><div class="panel"><b>Ventas cobradas</b><h2>${clp(summary.sales)}</h2></div><div class="panel"><b>Otros ingresos</b><h2>${clp(summary.movementIncome)}</h2></div><div class="panel"><b>Pagos a proveedores</b><h2>${clp(summary.supplierExpense)}</h2></div><div class="panel"><b>Otros egresos</b><h2>${clp(summary.otherExpense)}</h2></div><div class="panel"><b>Flujo neto registrado</b><h2>${clp(summary.net)}</h2></div></div><div class="cols"><section class="panel"><h2>Canales de venta</h2>${Object.entries(summary.channels).map(([key,x])=>`<div class="line"><span>${safe(CHANNELS[key])} · ${x.count} pedidos</span><b>${clp(x.total)}</b></div>`).join('')}</section><section class="panel"><h2>Medios de pago de ventas</h2>${Object.entries(summary.methods).map(([key,value])=>`<div class="line"><span>${safe(PAYMENT_NAMES[key])}</span><b>${clp(value)}</b></div>`).join('')}</section></div><p class="muted">Flujo neto = cobros de pedidos + otros ingresos − otros egresos − proveedores pagados. Usa la fecha efectiva de los movimientos de caja. No incluye comisiones de plataformas, impuestos, liquidaciones, devoluciones ni saldos bancarios.</p>${movementsResult.data.length===1000||suppliersResult.data.length===1000?'<p role="alert">Hay 1000 registros o más: el reporte puede estar incompleto. Acota o exporta desde la base.</p>':''}<button id="exportReport">Descargar detalle CSV</button>`;
  $('#reportDate').onchange=e=>{window.reportDay=e.target.value;renderOverview()};
  $('#exportReport').onclick=()=>{
    const rows=[['tipo','fecha','detalle','canal','medio','monto'],...movementsResult.data.filter(x=>!x.supplier_payment_id).map(x=>{const order=ordersResult.data.find(o=>o.id===x.order_id);return [x.order_id?'venta':'movimiento',x.created_at,x.order_id?'Pedido #'+(order?.order_number||x.order_id):x.description,x.order_id?CHANNELS[order?.source_channel]||'Local':'',PAYMENT_NAMES[x.method]||x.method,x.amount]}),...suppliersResult.data.map(x=>['proveedor',x.paid_at,x.supplier_name,'',PAYMENT_NAMES[x.method]||x.method,-x.amount])];
    const cell=value=>{const raw=String(value??'');const guarded=/^[=+@]/.test(raw)||/^-(?!\d+(?:\.\d+)?$)/.test(raw)?"'"+raw:raw;return '"'+guarded.replaceAll('"','""')+'"'};
    const file=new Blob(['\ufeff'+rows.map(row=>row.map(cell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(file),a=document.createElement('a');a.href=url;a.download=`reporte-${input}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
  };
}
async function renderSuppliers(){
  if(profile.role!=='owner')return;
  const [payments,sessions]=await Promise.all([sb.from('supplier_payments').select('*').order('created_at',{ascending:false}).limit(100),sb.from('cash_sessions').select('id').is('closed_at',null).limit(1)]);
  if(payments.error)return err(payments.error);
  const session=sessions.data?.[0]?.id||null;
  $('#view').innerHTML=`<h1>Proveedores</h1><form id="supplierForm" class="panel"><h2>Registrar obligación o pago</h2><label>Proveedor<input name="supplier" required minlength="2"></label><label>Concepto<input name="description" required minlength="3"></label><label>Monto<input name="amount" type="number" min="1" required></label><label>Medio<select name="method"><option value="transfer">Transferencia</option><option value="cash">Efectivo</option><option value="card">Tarjeta</option></select></label><label>Vencimiento<input name="due" type="date"></label><label class="checkline"><input type="checkbox" name="paid">Ya fue pagado</label><label class="checkline"><input type="checkbox" name="in_cash" ${session?'':'disabled'}>Registrar también como egreso en la caja abierta</label><p class="muted">Si no hay caja abierta, el pago queda igualmente registrado en proveedores. No vuelvas a ingresarlo como egreso manual.</p><button>Guardar</button></form><h2>Pagos y obligaciones</h2>${(payments.data||[]).map(x=>`<div class="panel"><b>${safe(x.supplier_name)}</b> · ${safe(x.description)}<br>${clp(x.amount)} · ${safe(PAYMENT_NAMES[x.method])} · ${x.status==='paid'?'Pagado '+new Date(x.paid_at).toLocaleDateString('es-CL'):'Pendiente'+(x.due_at?' · vence '+safe(x.due_at):'')}${x.status==='pending'?`<br><button data-pay-supplier="${x.id}">Marcar pagado</button>`:''}</div>`).join('')||'<p>Sin registros.</p>'}`;
  $('#supplierForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);if(f.has('in_cash')&&!f.has('paid'))return alert('Para registrar un egreso en caja, marca el pago como realizado.');let {error}=await sb.rpc('owner_record_supplier_payment',{p_supplier:f.get('supplier'),p_description:f.get('description'),p_amount:+f.get('amount'),p_method:f.get('method'),p_due:f.get('due')||null,p_paid:f.has('paid'),p_session:f.has('in_cash')?session:null});error?err(error):renderSuppliers()};
  document.querySelectorAll('[data-pay-supplier]').forEach(b=>b.onclick=async()=>{const register=session&&confirm('¿Registrar este pago también como egreso en la caja abierta?');const {error}=await sb.rpc('owner_pay_supplier',{p_id:b.dataset.paySupplier,p_session:register?session:null});error?err(error):renderSuppliers()});
}
