  const [people,jobs,journeys,entries,payments]=await Promise.all([sb.from('profiles').select('id,full_name').eq('role','courier'),sb.from('orders').select('courier_id,order_number,status').in('status',['assigned','out_for_delivery']),sb.from('courier_journeys').select('*').order('updated_at',{ascending:false}).limit(100),sb.from('time_entries').select('id,clock_in,clock_out').order('clock_in',{ascending:false}).limit(100),sb.rpc('courier_delivery_report',{p_day:day})]);
